#!/usr/bin/env node
// Reproducible read-only capture extraction. Original packets are never edited.
// Wireshark performs decryption using each public fixture's embedded DSB;
// these generated bytes are NOT plaintext bytes found on the captured wire.
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {readFileSync, mkdirSync, writeFileSync} from 'node:fs';
import {dirname, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {isDeepStrictEqual} from 'node:util';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const known = {
  'wireshark-http3-qpack': {path:'captures/wireshark-tests/wireshark-http3-qpack.pcapng', sha:'09aa88ee755cae2c441af94c7da2a2577de8d761d19b4521c753d10bcdd1d051', fragments:6, streams:4},
  'ndpi-doq': {path:'captures/ndpi/ndpi-doq.pcapng', fragments:8, streams:2},
};
const args = process.argv.slice(2);
const selected = [];
let tshark = process.env.TSHARK || 'tshark';
let check = false;
for (let i=0;i<args.length;i++) {
  if (args[i] === '--only' && known[args[i+1]]) selected.push(args[++i]);
  else if (args[i] === '--tshark' && args[i+1]) tshark = args[++i];
  else if (args[i] === '--check') check = true;
  else throw new Error('usage: extract-quic-streams.mjs [--only known-id] [--tshark path] [--check]');
}
const sha = b => createHash('sha256').update(b).digest('hex');
const array = v => v === undefined ? [] : Array.isArray(v) ? v : [v];
const one = v => array(v)[0];
const number = v => {
  const n = Number(one(v));
  if (!Number.isSafeInteger(n) || n < 0) throw new Error('invalid bounded numeric field');
  return n;
};
const specs = JSON.parse(readFileSync(resolve(root,'sources.json'),'utf8')).captures;
const version = execFileSync(tshark,['--version'],{encoding:'utf8'}).split('\n')[0].trim();
for (const id of selected.length ? selected : Object.keys(known)) {
  const source = known[id];
  const sourceSHA = sha(readFileSync(resolve(root,source.path)));
  const pinned = source.sha || specs.find(s=>s.id===id)?.source_sha256;
  if (sourceSHA !== pinned) throw new Error(`${id}: source digest differs from pinned provenance`);
  // Exclude ICMP quotations, which are not newly received QUIC stream data.
  // Disable external TLS key-log configuration. Embedded DSBs remain in scope.
  const command = ['-r',resolve(root,source.path),'-o','tls.keylog_file:','-Y','quic.stream_data && !icmp && !icmpv6','-T','json','-J','frame ip ipv6 udp quic','--no-duplicate-keys'];
  const packets = JSON.parse(execFileSync(tshark,command,{encoding:'utf8',maxBuffer:16*1024*1024}));
  const groups = new Map();
  let fragmentCount = 0;
  for (const packet of packets) {
    const l = packet._source.layers;
    const frame = number(l.frame['frame.number']);
    const src = one(l.ip?.['ip.src'] || l.ipv6?.['ipv6.src']);
    const dst = one(l.ip?.['ip.dst'] || l.ipv6?.['ipv6.dst']);
    const sport = number(l.udp['udp.srcport']), dport = number(l.udp['udp.dstport']);
    for (const q of array(l.quic)) for (const f of array(q['quic.frame'])) {
      if (!f['quic.stream_data']) continue;
      const streamID = number(f['quic.stream.stream_id']);
      const offset = f['quic.stream.offset'] === undefined ? 0 : number(f['quic.stream.offset']);
      const hex = one(f['quic.stream_data']).replaceAll(':','');
      if (!/^(?:[a-fA-F0-9]{2})*$/.test(hex)) throw new Error('invalid stream-data hex');
      const bytes = Buffer.from(hex,'hex');
      if (f['quic.stream.length'] !== undefined && number(f['quic.stream.length']) !== bytes.length) throw new Error('declared stream fragment length mismatch');
      const fin = number(f['quic.frame_type_tree']['quic.stream.fin']) === 1;
      const key = JSON.stringify([src,sport,dst,dport,streamID]);
      if (!groups.has(key)) groups.set(key,{stream_id:streamID,source_address:src,source_port:sport,destination_address:dst,destination_port:dport,fragments:[]});
      groups.get(key).fragments.push({frame,offset,length:bytes.length,fin,sha256:sha(bytes),hex});
      fragmentCount++;
    }
  }
  if (fragmentCount !== source.fragments || groups.size !== source.streams) throw new Error(`${id}: expected stream/fragment inventory changed`);
  const streams = [...groups.values()];
  for (const s of streams) {
    const size = Math.max(...s.fragments.map(f=>f.offset+f.length));
    if (size > 1024*1024) throw new Error('derived stream exceeds implementation limit');
    const bytes = Buffer.alloc(size), seen = Buffer.alloc(size);
    let finSize;
    for (const f of s.fragments) {
      const data = Buffer.from(f.hex,'hex');
      f.retransmission = data.length > 0 && data.every((b,i)=>seen[f.offset+i] && bytes[f.offset+i] === b);
      for (let i=0;i<data.length;i++) {
        const at = f.offset+i;
        if (seen[at] && bytes[at] !== data[i]) throw new Error('conflicting stream overlap');
        seen[at]=1; bytes[at]=data[i];
      }
      if (f.fin) {
        if (finSize !== undefined && finSize !== f.offset+f.length) throw new Error('conflicting FIN positions');
        finSize = f.offset+f.length;
      }
    }
    if (seen.includes(0) || (finSize !== undefined && finSize !== size)) throw new Error('gapped or inconsistent stream boundary');
    s.length=size; s.sha256=sha(bytes); s.hex=bytes.toString('hex');
    s.fin_observed=finSize !== undefined;
    s.boundary=s.fin_observed?'observed FIN':'contiguous observed prefix; stream end not observed';
  }
  const document = {
    schema_version:1,source_capture:source.path,source_capture_sha256:sourceSHA,
    extraction:{tool:version,command:command.map(a=>a===resolve(root,source.path)?source.path:a),input_keys:'public source capture embedded DSB; external TLS keylog disabled',coordinates:'decrypted QUIC stream byte offsets, not original packet wire offsets',binparser_decryption_performed:false,icmp_quotations_excluded:true},
    fragment_count:fragmentCount,stream_count:streams.length,streams,
  };
  const output = resolve(root,'derived',`${id}.streams.json`);
  if (check) {
    const expected = JSON.parse(readFileSync(output,'utf8'));
    // Tool-version text may change; every source, command and stream byte must
    // still match. Verification never rewrites the recorded extraction tool.
    expected.extraction.tool = version;
    if (!isDeepStrictEqual(document,expected)) throw new Error(`${id}: derived stream evidence differs from stored fixture`);
  } else {
    mkdirSync(resolve(root,'derived'),{recursive:true});
    writeFileSync(output,JSON.stringify(document,null,2)+'\n');
  }
  process.stdout.write(`${id}: ${streams.length} streams, ${fragmentCount} fragments, ${streams.map(s=>s.length).join('/')} bytes\n`);
}
